"""Import unabridged local NESA sources. No syllabus text is generated by this script."""
from pathlib import Path
from zipfile import ZipFile
from xml.etree import ElementTree as ET
import json, re

ROOT=Path(__file__).resolve().parents[2]
DEST=Path(__file__).resolve().parents[1]/'content'
DEST.mkdir(exist_ok=True)
SUBJECTS=[('english','English Standard','english/english-standard-11-12-2024',2024),('maths','Mathematics Advanced','mathematics/mathematics-advanced-11-12-2024',2024),('extension','Mathematics Extension 1','mathematics/mathematics-extension-1-11-12-2024',2024),('biology','Biology','science/biology-11-12-2025',2025),('physics','Physics','science/physics-11-12-2025',2025),('software','Software Engineering - Distance Education','tas/software-engineering-11-12-2022',2022)]
ns={'w':'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
def extract_text(el):
    tag=el.tag.split('}')[-1]
    if tag=='t': return el.text or ''
    if tag=='tab': return ' '
    if tag=='br': return '\n'
    if el.tag.startswith('{http://schemas.openxmlformats.org/officeDocument/2006/math}'):
        children={x.tag.split('}')[-1]:x for x in el}
        get=lambda name: extract_text(children[name]) if name in children else ''
        if tag=='f': return '('+get('num')+')/('+get('den')+')'
        if tag=='sSup': return '('+get('e')+')^('+get('sup')+')'
        if tag=='sSub': return get('e')+'_'+get('sub')
        if tag=='sSubSup': return get('e')+'_'+get('sub')+'^('+get('sup')+')'
        if tag=='rad': return 'sqrt('+get('e')+')'
    return ''.join(extract_text(child) for child in el)
documents=[]
for sid,folder,slug,version in SUBJECTS:
    file=ROOT/folder/'NESA - full syllabus.docx'
    paragraphs=[]
    if file.exists():
        with ZipFile(file) as z:
            doc=ET.fromstring(z.read('word/document.xml'))
            for p in doc.findall('.//w:body//w:p',ns):
                text=extract_text(p).strip()
                if text: paragraphs.append(text)
    else:
        alternative=ROOT/folder/'NESA - full syllabus.txt'
        if alternative.exists(): paragraphs=[p.strip() for p in alternative.read_text(encoding='utf-8').splitlines() if p.strip()]
    url=f'https://curriculum.nsw.edu.au/learning-areas/{slug}'
    outcomes={}
    for index,p in enumerate(paragraphs):
        for code in re.findall(r'\b(?:MA|ME1|EST|BI|PY|SE)[A-Z0-9]*-(?:11|12)(?:WS)?-\d{2}\b',p):
            description=p.replace(code,'').strip(' :–—-')
            if len(description)<20: description=paragraphs[index+1] if index+1<len(paragraphs) else code
            if 'WS-' in code and index+2<len(paragraphs) and not re.search(r'\b[A-Z]+-\d',paragraphs[index+2]): description+=': '+paragraphs[index+2]
            if code not in outcomes:
                outcomes[code]={'code':code,'description':description[:1800]}
    points=[];current_codes=[];in_content=False;point_seen=set()
    for index,p in enumerate(paragraphs):
        codes=re.findall(r'\b(?:MA|ME1|EST|BI|PY|SE)[A-Z0-9]*-(?:11|12)(?:WS)?-\d{2}\b',p)
        if p=='Outcomes': current_codes=[];in_content=False
        if codes:
            current_codes=list(dict.fromkeys(current_codes+codes))
        if p=='Content': in_content=True
        if p in ['Assessment','Glossary']: in_content=False
        if in_content and not codes and 35<=len(p)<=650 and re.match(r'^(Use|Explain|Describe|Analyse|Analyze|Evaluate|Assess|Compare|Contrast|Calculate|Solve|Apply|Investigate|Explore|Examine|Determine|Identify|Interpret|Construct|Conduct|Design|Develop|Justify|Recognise|Graph|Prove|Model|Represent|Compose|Experiment|Reflect|The ways|The power)\b',p) and p not in point_seen and current_codes:
            point_seen.add(p);year=12 if all('-12' in c for c in current_codes) else 11
            points.append({'index':index,'text':p,'codes':current_codes.copy(),'year':year})
    documents.append({'id':sid,'name':folder,'version':version,'url':url+'/overview','contentUrl':url+'/content','localFile':str(file.relative_to(ROOT)) if file.exists() else None,'imported':bool(paragraphs),'paragraphs':paragraphs,'outcomes':list(outcomes.values()),'points':points,'provisional':False,'provider':'Sydney Distance Education High School' if sid=='software' else None,'checked':'2026-11-10'})
    print(sid,len(paragraphs),'paragraphs;',len(outcomes),'outcomes')
(DEST/'curriculum.json').write_text(json.dumps(documents,ensure_ascii=False,indent=2),encoding='utf-8')
